func newRolloutAssignment() unsafe.Pointer {
	return unsafe.Pointer(new(extractionrollout.RolloutAssignment))
}

func newNRolloutAssignment(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]extractionrollout.RolloutAssignment, n)))
}

func ptrRolloutAssignment(p unsafe.Pointer, c int32) any {
	r := (*extractionrollout.RolloutAssignment)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.DocumentID))
	case 4:
		return &r.ExtractedAt
	case 5:
		return (*string)(unsafe.Pointer(&r.Arm))
	case 6:
		return (*string)(unsafe.Pointer(&r.CandidateProviderID))
	case 7:
		return (**string)(unsafe.Pointer(&r.ServedProviderID))
	case 8:
		return &r.ServedModel
	case 9:
		return (*string)(unsafe.Pointer(&r.Outcome))
	case 10:
		return &r.SettledAt
	case 11:
		return &r.Version
	case 12:
		return &r.CreatedAt
	case 13:
		return &r.UpdatedAt
	}
	return nil
}

func valueRolloutAssignment(p unsafe.Pointer, c int32) any {
	r := (*extractionrollout.RolloutAssignment)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.DocumentID)
	case 4:
		return r.ExtractedAt
	case 5:
		return string(r.Arm)
	case 6:
		return string(r.CandidateProviderID)
	case 7:
		if r.ServedProviderID == nil {
			return nil
		}
		return string(*r.ServedProviderID)
	case 8:
		if r.ServedModel == "" {
			return nil
		}
		return r.ServedModel
	case 9:
		return string(r.Outcome)
	case 10:
		if r.SettledAt == nil {
			return nil
		}
		return *r.SettledAt
	case 11:
		return r.Version
	case 12:
		return r.CreatedAt
	case 13:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateRolloutAssignment(ctx context.Context, p unsafe.Pointer) error {
	return (*extractionrollout.RolloutAssignment)(p).BeforeCreate(ctx)
}

